func DispatchKimi(d, p, m byte, vec *KimiStateVector) error {
	identity, err := ResolveKimiIdentity(d, p, m)
	if err != nil {
		return err
	}
	handler := KimiTable[identity.Code]
	if handler == nil {
		return errors.New("kimi kernel not initialized")
	}
	return handler(identity, vec)
}

func GetKimiExecutionCount(code uint16) uint64 {
	if code >= 1000 {
		return 0
	}
	return atomic.LoadUint64(&KimiMetrics[code])
}
